import {maintenanceAlerts,capitalRemaining} from '../domain/fleet-view.js';
import {driverSummary,missingSalaryMonths} from '../domain/drivers.js';
import * as Base from '../domain/core.js';
import * as Fleet from '../domain/fleet.js';
const C={...Base,validate:Fleet.validateFleet,demo:Fleet.demo,backup:Fleet.backup,parseBackup:Fleet.parseBackup,stats:(s,from,to)=>Fleet.fleetStats(s,from,to,scope),ledger:s=>Base.ledger(scope?Fleet.vehicleState(s,scope):s)};
let scope='',driverScope='';
const currentVehicle=()=>state.vehicles.find(v=>v.id===scope)||state.vehicles[0];
const loansInScope=()=>state.loans.filter(l=>!scope||state.loanVehicles.some(a=>a.loanId===l.id&&a.vehicleId===scope));
const currentDriver=()=>state.drivers.find(d=>d.id===driverScope)||state.drivers[0];
import * as DB from '../app-store.js';
let state=null,page='dashboard',from=C.today().slice(0,8)+'01',to=C.today(),statusFilter='',search='',busy=false;
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(n)+' '+state.settings.currency;
const num=n=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(n);
const date=d=>d?d.split('-').reverse().join('/'):'—';
const nav=[['dashboard','◫','Tableau de bord'],['fleet','▱','Véhicules'],['days','↗','Versements'],['expenses','−','Dépenses'],['maintenance','◇','Entretien'],['driver','◎','Chauffeur'],['loans','▤','Prêt'],['cash','⇄','Trésorerie'],['simulation','⌁','Simulation'],['reports','▥','Rapports'],['settings','⚙','Paramètres'],['backup','↓','Sauvegarde']];
function toast(m){$('#toast').textContent=m;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500);}
function error(e){toast(e.message||String(e));}
async function commit(next){if(busy)throw Error('Un enregistrement est déjà en cours.');busy=true;try{state=await DB.save(next,state?.revision??null);}finally{busy=false;}render();}
async function mutate(fn){let next=structuredClone(state);fn(next);await commit(next);}
const selected=a=>a.filter(x=>C.inPeriod(x,from,to)&&(!scope||!x.vehicleId||x.vehicleId===scope));
function cards(items){return `<div class="cards">${items.map(([label,val,hint,highlight])=>`<div class="card ${highlight?'highlight':''}"><div class="label">${label}</div><div class="value">${val}</div><div class="hint">${hint||'Période sélectionnée'}</div></div>`).join('')}</div>`;}
function table(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map((c,i)=>`<td data-label="${esc(headers[i])}">${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">Aucune opération pour cette période.</td></tr>`}</tbody></table></div>`;}
const buttons=(collection,id)=>`<button data-edit="${collection}" data-id="${esc(id)}" aria-label="Modifier l’opération">Modifier</button> <button data-delete="${collection}" data-id="${esc(id)}" aria-label="Supprimer l’opération">Supprimer</button>`;
const sign=n=>`<span class="${n<0?'negative':'positive'}">${money(n)}</span>`;
function period(){return `<div class="filters no-print"><label>Période<select id="preset"><option value="custom">Personnalisée</option value="day">Aujourd’hui</option><option value="week">Cette semaine</option><option value="month">Ce mois</option><option value="year">Cette année</option><option value="all">Tout l’historique</option></select></label><label>Du<input type="date" id="from" value="${from}"></label><label>Au<input type="date" id="to" value="${to}"></label><button id="apply-period">Appliquer</button></div>`;}
function render(){if(!state){$('#workspace').innerHTML=`<div class="welcome"><a class="brand" href="/"><img src="/brand/icon.webp" alt="NR-TRANS" width="46" height="46"><span>NR-TRANS<small>Gestion de transport</small></span></a><h1>Votre activité.<br>Des comptes clairs.</h1><p>Versements, chauffeur, dépenses et prêt : réunissez le suivi de votre véhicule dans un seul espace, même sans Internet.</p><div class="panel"><h2>Comment souhaitez-vous commencer ?</h2><p class="sub">La démonstration contient des opérations fictives sur trois mois. Vous pourrez tout effacer avant de saisir vos vrais chiffres.</p><div class="actions"><button class="primary" id="start-demo">Explorer la démonstration</button><button id="start-empty">Commencer avec une base vide</button></div></div><p class="sub">Vos données sont conservées dans ce navigateur. Téléchargez régulièrement une sauvegarde JSON : effacer les données du navigateur efface aussi vos comptes locaux.</p></div>`;if(!DB.isDemo())$('#start-demo').remove();if($('#start-demo'))$('#start-demo').onclick=()=>commit(C.demo()).catch(error);$('#start-empty').onclick=()=>commit(C.blank()).then(()=>{page='settings';render();}).catch(error);return;}
const names=Object.fromEntries(nav.map(([id,_,name])=>[id,name]));
$('#workspace').innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="/"><img src="/brand/icon.webp" alt="NR-TRANS" width="46" height="46"><span>NR-TRANS<small>Gestion de transport</small></span></a><nav aria-label="Navigation principale">${nav.map(([id,icon,name])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${name}</button>`).join('')}</nav><footer>${esc(currentVehicle().name)}<br>${esc(currentVehicle().plate||'Immatriculation à renseigner')}<br><span id="offline-status">${navigator.onLine?'Stockage local':'Hors connexion'}</span></footer></aside><main class="main"><div class="topline"><div class="actions"><button class="mobile-menu" id="menu" aria-label="Ouvrir le menu">☰</button><span>MON ACTIVITÉ / ${names[page].toUpperCase()}</span></div><span class="tag ${state.demo?'demo':''}">${state.demo?'DONNÉES DE DÉMONSTRATION':'Données de votre activité'}</span></div><div class="fleet-filter"><label>Vue du parc<select id="vehicle-scope"><option value="">Tous les véhicules</option>${state.vehicles.map(v=>`<option value="${esc(v.id)}" ${v.id===scope?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label><label>Chauffeur<select id="driver-scope">${state.drivers.map(d=>`<option value="${esc(d.id)}" ${d.id===currentDriver().id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label></div><div class="heading"><div><h1>${names[page]}</h1><p class="sub">${subtitle()}</p></div><div class="actions">${headingActions()}</div></div>${['settings','backup','simulation'].includes(page)?'':period()}<div id="content">${content()}</div></main></div>`;
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;statusFilter='';search='';render();window.scrollTo(0,0);});$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');bind();}
function subtitle(){return {fleet:'Votre parc, vos véhicules et leurs performances.',dashboard:'Une vue claire sur votre activité de transport.',days:'Un relevé par jour. Des versements et des écarts traçables.',expenses:'Les coûts de votre activité, au même endroit.',maintenance:'Anticipez les interventions et suivez leur coût.',driver:'Distinguez la rémunération acquise des paiements effectués.',loans:'Les échéances prévues et les remboursements réellement payés.',cash:'Chaque entrée et chaque sortie, reliée à son origine.',simulation:'Testez vos hypothèses sans modifier vos comptes.',reports:`Du ${date(from)} au ${date(to)} · prêt à imprimer.`,settings:'Vos informations et vos règles pour les prochaines opérations.',backup:'Gardez une copie de vos comptes, sous votre contrôle.'}[page];}
function headingActions(){const actions={fleet:'<button class="primary" id="add-vehicle">+ Ajouter un véhicule</button>',dashboard:'<button class="primary" data-add="days">+ Nouveau versement</button>',days:'<button class="primary" data-add="days">+ Nouvelle journée</button>',expenses:'<button class="primary" data-add="expenses">+ Nouvelle dépense</button>',maintenance:'<button class="primary" data-add="maintenance">+ Nouvel entretien</button>',driver:'<button data-add="wages">+ Salaire mensuel dû</button><button class="primary" data-add="driverPayments">+ Paiement chauffeur</button>',loans:'<button data-add="loans">+ Nouveau prêt</button><button class="primary" data-add="loanPayments">+ Enregistrer un paiement</button>',cash:'<button class="primary" data-add="movements">+ Mouvement manuel</button>',reports:'<button id="print">Imprimer le rapport</button>'};return actions[page]||'';}
function content(){return {fleet:fleetPage,dashboard:dashboard,days:daysPage,expenses:expensesPage,maintenance:maintenancePage,driver:driverPage,loans:loansPage,cash:cashPage,simulation:simulationPage,reports:reportsPage,settings:settingsPage,backup:backupPage}[page]();}
function chart(){const end=to.slice(0,8)+'01',months=Array.from({length:6},(_,i)=>{const first=C.addPeriod(end,i-5),last=C.addPeriod(first,1);return {month:first.slice(0,7),...C.stats(state,first,new Date(Date.parse(last)-86400000).toISOString().slice(0,10))};});const max=Math.max(1,...months.flatMap(m=>[m.revenue,m.costs+m.wage+m.interest,Math.abs(m.profit)]));return `<div class="legend"><span><i style="background:#0d8776"></i>Versements</span><span><i style="background:#e1a448"></i>Charges dues</span><span><i style="background:#6d8997"></i>Résultat</span></div><div class="chart" role="img" aria-label="Comparaison des six derniers mois ; valeurs dans le tableau ci-dessous">${months.map(m=>`<div class="bar-group"><div class="bars"><div class="bar" style="height:${m.revenue/max*100}%" title="Versements : ${money(m.revenue)}"></div><div class="bar expense" style="height:${(m.costs+m.wage+m.interest)/max*100}%" title="Charges : ${money(m.costs+m.wage+m.interest)}"></div><div class="bar net" style="height:${Math.abs(m.profit)/max*100}%;background:${m.profit<0?'#b32d35':'#6d8997'}" title="Résultat : ${money(m.profit)}"></div></div><span>${m.month.slice(5)}/${m.month.slice(2,4)}</span></div>`).join('')}</div><details><summary>Voir les chiffres mensuels</summary>${table(['Mois','Versements','Charges dues','Résultat'],months.map(m=>[m.month,money(m.revenue),money(m.costs+m.wage+m.interest),sign(m.profit)]))}</details>`;}
function alertMaintenance(){return maintenanceAlerts(state,scope);}
function dashboard(){const s=C.stats(state,from,to),all=C.stats(state,'0000-01-01',to),loanRemaining=capitalRemaining(state,scope),todayRevenue=C.stats(state,C.today(),C.today()).revenue;const alerts=alertMaintenance();const due=loansInScope().flatMap(l=>C.schedule(state,l).filter(e=>e.remaining>0).slice(0,1).map(e=>({...e,lender:l.lender})));
return `${!state.settings.lastBackup||Date.now()-Date.parse(state.settings.lastBackup)>7*86400000?'<div class="notice warn">Pensez à sauvegarder vos données. <button data-page="backup">Ouvrir les sauvegardes</button></div>':''}${cards([['Versements reçus',money(s.revenue),`Aujourd’hui : ${money(todayRevenue)}`,true],['Résultat d’exploitation',sign(s.profit),'Après rémunération due et intérêts payés'],['Trésorerie disponible',money(s.balance),`Solde cumulé au ${date(to)}`],['Capital restant dû',money(loanRemaining),'À ce jour · tous paiements enregistrés']])}<div class="grid2"><section class="panel"><h2>Votre activité sur 6 mois</h2>${chart()}</section><section class="panel"><h2>Objectif et réalisation</h2><div class="metricrow"><span>Versements attendus</span><b>${money(s.expected)}</b></div><div class="metricrow"><span>Versements reçus</span><b>${money(s.revenue)}</b></div><div class="metricrow"><span>Écart</span><b>${sign(s.gap)}</b></div><div class="progress"><div style="width:${Math.min(100,s.expected?s.revenue/s.expected*100:0)}%"></div></div><div class="metricrow"><span>Jours travaillés / sans activité</span><b>${s.worked} / ${s.idle}</b></div><div class="metricrow"><span>Distance parcourue</span><b>${num(s.km)} km</b></div><p class="sub">Les jours non saisis ne sont pas comptés comme jours de repos.</p></section></div>${cards([['Dépenses payées',money(s.costs),'Entretien et carburant propriétaire inclus'],['Rémunération due',money(s.wage),`Reste cumulé : ${money(all.wage-all.paid)}`],['Remboursements du prêt',money(s.loanPaid),'Capital, intérêts et frais payés'],['Flux net de trésorerie',sign(s.cashChange),'Entrées moins sorties de la période']])}<div class="grid2"><section class="panel"><h2>Échéances à venir ou en retard</h2><p class="sub">Montants des contrats complets liés à la sélection.</p>${due.length?due.map(e=>`<div class="metricrow"><span>${esc(e.lender)}<br><small>${date(e.date)} ${e.date<C.today()?'· En retard':''}</small></span><b>${money(e.remaining)}</b></div>`).join(''):'<p class="sub">Aucune échéance en attente.</p>'}</section><section class="panel"><h2>Entretien à surveiller</h2>${alerts.length?alerts.map(m=>`<div class="metricrow"><span>${esc(state.vehicles.find(v=>v.id===m.vehicleId)?.name)} · ${esc(m.type)}</span><b>${m.nextDate?date(m.nextDate):''} ${m.nextKm?' · '+num(m.nextKm)+' km':''}</b></div>`).join(''):'<p class="sub">Aucun entretien proche ou dépassé.</p>'}<p class="backup-date">Dernière sauvegarde téléchargée : ${state.settings.lastBackup?new Date(state.settings.lastBackup).toLocaleString('fr-FR'):'aucune'}</p></section></div><details><summary>Comprendre les indicateurs</summary><p>Le résultat correspond aux versements moins les dépenses, l’entretien, le carburant payé par les propriétaires, la rémunération acquise et les intérêts/frais du prêt payés. Le remboursement du capital, l’achat du véhicule, les apports et les retraits affectent la trésorerie, pas ce résultat. Celui-ci est calculé avant amortissement du véhicule et fiscalité non saisie. Les recettes encaissées auprès des passagers par le chauffeur ne sont pas connues : ici, « recettes » désigne ses versements aux propriétaires.</p><p>En mode fixe, enregistrez une ligne « Salaire mensuel dû » dans Chauffeur pour chaque mois. Une alerte rappelle les mois travaillés sans salaire enregistré. Les commissions sont dues en plus du versement reçu, jamais déjà retenues dans ce montant.</p></details>${missingWages()}`;}
function missingWages(driverId=''){const months=missingSalaryMonths(state,driverId,scope);return months.length?'<div class="notice warn">Salaire fixe à enregistrer pour : '+months.map(m=>esc(state.drivers.find(d=>d.id===m.driverId)?.name)+' · '+m.month).join(', ')+'. Le résultat reste incomplet tant que ces salaires ne sont pas saisis.</div>':'';}
function daysPage(){const a=selected(state.days).filter(d=>(!statusFilter||d.status===statusFilter)&&(!search||(d.comment+' '+d.incident).toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="panel"><div class="filters"><label>Statut<select id="status-filter"><option value="">Tous les statuts</option>${['Travaillé','Repos','Panne','Entretien','Indisponible','Autre'].map(x=>`<option ${x===statusFilter?'selected':''}>${x}</option>`).join('')}</select></label><label>Commentaire ou incident<input id="search" value="${esc(search)}" placeholder="Rechercher"></label><button id="filter-search">Rechercher</button></div>${table(['Date','Statut','Attendu','Reçu','Écart','Commission','Km','Commentaire / incident','Actions'],a.map(d=>[date(d.date),esc(d.status),money(d.expected),money(d.actual),sign(d.actual-d.expected),money(C.dayWage(d)),num(d.kmEnd-d.kmStart),esc(d.comment)+' '+esc(d.incident),buttons('days',d.id)]))}<p class="sub">${a.length} journée(s) · ${money(C.sum(a,x=>x.actual))} reçus</p></div>`;}
function expensesPage(){const a=selected(state.expenses).filter(e=>!statusFilter||e.category===statusFilter).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="notice">Les entretiens saisis dans Entretien sont déjà déduits de la trésorerie. Saisissez les remboursements dans Prêt et les paiements du chauffeur dans Chauffeur pour éviter les doublons.</div><section class="panel"><div class="filters"><label>Catégorie<select id="status-filter"><option value="">Toutes les catégories</option>${[...new Set([...state.settings.categories,...state.expenses.map(e=>e.category)])].map(c=>`<option ${c===statusFilter?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div>${table(['Date','Catégorie','Description','Montant','Paiement','Actions'],a.map(e=>[date(e.date),esc(e.category),esc(e.description),money(e.amount),esc(e.method),buttons('expenses',e.id)]))}<p><b>Total : ${money(C.sum(a))}</b></p></section><section class="panel"><h2>Répartition des dépenses</h2>${[...new Set(a.map(e=>e.category))].map(c=>`<div class="metricrow"><span>${esc(c)}</span><b>${money(C.sum(a.filter(e=>e.category===c)))}</b></div>`).join('')||'<p class="sub">Aucune dépense.</p>'}</section>`;}
function maintenancePage(){const alerts=new Set(alertMaintenance().map(m=>m.id));return `<div class="notice">Le coût de chaque intervention est considéré comme payé à sa date et inclus une seule fois dans les dépenses et la trésorerie. Après la prochaine intervention, retirez le rappel de l’ancienne fiche et créez la nouvelle.</div><section class="panel">${table(['Date','Intervention','Km','Coût','Prestataire','Prochaine date','Prochain km','Actions'],selected(state.maintenance).sort((a,b)=>b.date.localeCompare(a.date)).map(m=>[date(m.date),esc(m.type)+(alerts.has(m.id)?' <span class="tag demo">À prévoir</span>':''),num(m.km),money(m.cost),esc(m.provider),date(m.nextDate),m.nextKm?num(m.nextKm):'—',buttons('maintenance',m.id)]))}</section>`;}
function driverPage(){const d=currentDriver(),s=driverSummary(state,d.id,from,to,scope),all=driverSummary(state,d.id,'0000-01-01',to,scope);return `${missingWages(d.id)}<section class="panel"><h2>${esc(d.name)}</h2><p class="sub">${esc(d.phone||'Téléphone non renseigné')} · Depuis le ${date(d.startDate)} · ${esc(d.status)}</p><p>${d.mode==='fixed'?'Salaire fixe : '+money(d.salary)+' / mois':'Commission : '+money(d.commission)+' pour '+money(d.tranche)+' · '+(d.rule==='full'?'tranches complètes par journée':'calcul proportionnel par journée')}</p><button data-page="settings">Modifier la fiche et les règles</button></section>${cards([['Rémunération acquise',money(s.wage),'Commissions + salaires mensuels saisis'],['Paiements effectués',money(s.paid),'Paiements de la période'],['Reste à payer cumulé',sign(all.wage-all.paid),'Négatif : avance au chauffeur'],['Jours travaillés',num(s.worked),`${money(s.revenue)} versés · écart ${money(s.gap)}`]])}<div class="notice">Le salaire fixe n’est pas ajouté automatiquement. Enregistrez chaque mois sa rémunération due, puis les paiements séparément. Un mois partiel peut être proratisé manuellement ; indiquez votre calcul dans le commentaire. Les commissions sont calculées sur le versement reçu et conservées avec chaque journée.</div><section class="panel"><h2>Salaires mensuels dus</h2>${table(['Mois','Montant dû','Commentaire','Actions'],selected(state.wages).filter(w=>w.driverId===d.id).map(w=>[w.date.slice(0,7),money(w.amount),esc(w.comment),buttons('wages',w.id)]))}</section><section class="panel"><h2>Paiements effectués</h2>${table(['Date','Montant','Commentaire','Actions'],selected(state.driverPayments).filter(p=>p.driverId===d.id).map(p=>[date(p.date),money(p.amount),esc(p.comment),buttons('driverPayments',p.id)]))}</section>`;}
function loansPage(){const visible=loansInScope();if(!visible.length)return '<section class="panel empty">Configurez le prêt pour afficher l’échéancier et saisir les remboursements.</section>';return visible.map(l=>{const schedule=C.schedule(state,l),balance=C.loanBalance(state,l.id),paid=C.sum(state.loanPayments.filter(p=>p.loanId===l.id),p=>p.principal+p.interest+p.fees),paidCount=schedule.filter(e=>e.remaining===0).length;return `<section class="panel"><div class="heading"><div><h2>${esc(l.lender)}</h2><p class="sub">Affectations : ${state.loanVehicles.filter(a=>a.loanId===l.id).map(a=>esc(state.vehicles.find(v=>v.id===a.vehicleId)?.name)+' · '+money(a.amount)).join(' ; ')}</p><p class="sub">Les montants et l’échéancier ci-dessous concernent le contrat complet. Les rapports par véhicule utilisent les allocations.</p><p class="sub">${l.count} échéances ${l.frequency==='weekly'?'hebdomadaires':'mensuelles'} · Taux nominal annuel ${num(l.rate)} %</p></div>${buttons('loans',l.id)}</div>${cards([['Capital emprunté',money(l.principal),'Montant du contrat'],['Total payé',money(paid),'Capital, intérêts et frais'],['Capital restant',money(balance),'Paiements réellement saisis'],['Échéances soldées',paidCount+' / '+l.count,'Sur la base des paiements affectés']])}<div class="progress"><div style="width:${l.principal?(l.principal-balance)/l.principal*100:0}%"></div></div><p class="sub">Échéance habituelle : ${money(l.payment)}. Apport prévu : ${money(l.downPayment)}. Frais contractuels : ${money(l.fees)} (à enregistrer lorsqu’ils sont payés).</p><p class="sub">Le contrat ne crée aucun mouvement automatique d’achat, d’apport ou de déblocage : enregistrez ces mouvements dans Trésorerie. L’échéancier reste celui du contrat ; un remboursement anticipé réduit le capital réel, mais ne recalcule pas le contrat.</p></section><section class="panel"><h2>Échéancier contractuel</h2>${table(['N°','Date','À payer','Capital prévu','Intérêts prévus','Paiements affectés','État'],schedule.map(e=>[e.number,date(e.date),money(e.payment),money(e.principal),money(e.interest),money(e.paid),e.remaining===0?'Payée':e.paid>0?'Partielle':e.date<C.today()?'<span class="negative">En retard</span>':'À venir']))}</section><section class="panel"><h2>Paiements enregistrés · période sélectionnée</h2>${table(['Date','Échéance','Capital','Intérêts','Frais','Actions'],selected(state.loanPayments).filter(p=>p.loanId===l.id).map(p=>[date(p.date),p.installment,money(p.principal),money(p.interest),money(p.fees),buttons('loanPayments',p.id)]))}</section>`;}).join('');}
function cashPage(){const s=C.stats(state,from,to);let balance=0;const all=C.ledger(state).map(x=>({...x,balance:balance=C.round(balance+x.amount)}));return `${cards([['Entrées',money(s.inflow),'Sur la période'],['Sorties',money(s.outflow),'Sur la période'],['Variation',sign(s.cashChange),'Entrées moins sorties'],['Solde cumulé',money(s.balance),`Au ${date(to)}`,true]])}<section class="panel"><h2>Registre de trésorerie</h2>${table(['Date','Opération','Entrée','Sortie','Solde','Origine'],selected(all).reverse().map(x=>[date(x.date),esc(x.label),x.amount>=0?money(x.amount):'—',x.amount<0?money(-x.amount):'—',money(x.balance),x.source==='movements'?buttons('movements',x.sourceId):`<button data-edit="${x.source}" data-id="${esc(x.sourceId)}">Voir / modifier l’origine</button>`]))}</section><section class="panel"><h2>Apports et retraits des propriétaires · période sélectionnée</h2>${table(['Propriétaire','Apports','Retraits','Apport net'],state.owners.map(o=>{const a=selected(state.movements).filter(m=>m.ownerId===o.id),inflow=C.sum(a.filter(m=>m.type==='Apport propriétaire')),out=C.sum(a.filter(m=>m.type==='Retrait propriétaire'));return [esc(o.name),money(inflow),money(out),money(inflow-out)];}))}</section>`;}
function reportsPage(){const s=C.stats(state,from,to);let months={};for(const d of selected(C.ledger(state)))months[d.date.slice(0,7)]=true;for(const d of selected(state.wages))months[d.date.slice(0,7)]=true;return `<div class="report-only"><p>${scope?esc(currentVehicle().name)+' · '+esc(currentVehicle().plate):'Ensemble du parc'} · ${state.demo?'DONNÉES DE DÉMONSTRATION':''}</p></div>${cards([['Versements',money(s.revenue),'Réellement reçus'],['Résultat d’exploitation',money(s.profit),'Avant amortissement et fiscalité non saisie'],['Flux de trésorerie',money(s.cashChange),'Entrées − sorties'],['Kilomètres',num(s.km)+' km',s.worked+' jours travaillés']])}<section class="panel"><h2>Synthèse de la période</h2>${table(['Indicateur','Montant'],[['Attendu',money(s.expected)],['Versements reçus',money(s.revenue)],['Écart',money(s.gap)],['Dépenses et entretiens payés',money(s.costs)],['Rémunération due',money(s.wage)],['Chauffeur payé',money(s.paid)],['Intérêts et frais du prêt payés',money(s.interest)],['Remboursements du prêt (capital inclus)',money(s.loanPaid)],['Résultat d’exploitation',money(s.profit)],['Trésorerie en fin de période',money(s.balance)]] )}</section><section class="panel"><h2>Détail mensuel et évolution du solde</h2>${table(['Mois','Attendu','Reçu','Dépenses','Chauffeur dû','Prêt payé','Résultat','Solde cumulé'],Object.keys(months).sort().map(m=>{const first=m+'-01',last=new Date(Date.parse(C.addPeriod(first,1))-86400000).toISOString().slice(0,10),x=C.stats(state,first<from?from:first,last>to?to:last);return[m,money(x.expected),money(x.revenue),money(x.costs),money(x.wage),money(x.loanPaid),money(x.profit),money(x.balance)];}))}</section>${missingWages()}<p class="sub">Les apports, retraits, achats de véhicule et remboursements du capital ne sont pas des charges d’exploitation. Les dépenses sont suivies à leur paiement ; les commissions et salaires enregistrés sont suivis lorsqu’ils sont dus.</p>`;}
const field=(name,label,type='text',options=null,value='',extra='')=>({name,label,type,options,value,extra});
function input(f,v){v=v??f.value??'';const options=f.options?.map(o=>Array.isArray(o)?o:[o,o]);return `<label class="${f.type==='textarea'?'wide':''}">${f.label}${f.type==='select'?`<select name="${f.name}" ${f.extra}>${options.map(([key,label])=>`<option value="${esc(key)}" ${String(v)===String(key)?'selected':''}>${esc(label)}</option>`).join('')}</select>`:f.type==='textarea'?`<textarea name="${f.name}" ${f.extra}>${esc(v)}</textarea>`:`<input name="${f.name}" type="${f.type}" value="${esc(v)}" ${f.type==='number'?'min="0" max="1000000000000" step="0.01"':''} ${f.extra}>`}</label>`;}
function getValues(form,fields){const fd=new FormData(form),v={};for(const f of fields)v[f.name]=f.type==='number'?Number(fd.get(f.name)):String(fd.get(f.name)??'').trim();return v;}
function schema(collection){const d=currentDriver(),v=currentVehicle(),lastKm=Math.max(v.initialKm,...state.days.filter(d=>d.vehicleId===v.id).map(d=>d.kmEnd));const common=[field('date','Date','date',null,C.today(),'required')];const amount=field('amount','Montant ('+state.settings.currency+')','number',null,0,'required');const comment=field('comment','Commentaire','textarea');switch(collection){
case 'days':return [...common,field('vehicleId','Véhicule','select',state.vehicles.map(v=>[v.id,v.name]),currentVehicle().id),field('driverId','Chauffeur','select',state.drivers.map(d=>[d.id,d.name]),currentDriver().id),field('status','Statut de la journée','select',['Travaillé','Repos','Panne','Entretien','Indisponible','Autre'],'Travaillé'),field('expected','Versement attendu','number',null,state.settings.target,'required'),field('actual','Versement reçu','number',null,state.settings.target,'required'),field('kmStart','Kilométrage départ','number',null,lastKm,'required'),field('kmEnd','Kilométrage arrivée','number',null,lastKm,'required'),field('fuel','Carburant dépensé','number',null,0),field('fuelPayer','Carburant payé par','select',[['driver','Le chauffeur'],['owner','Les propriétaires']],state.settings.fuelPayer),comment,field('incident','Incident éventuel','textarea')];
case 'expenses':return [...common,field('vehicleId','Véhicule','select',state.vehicles.map(v=>[v.id,v.name]),currentVehicle().id),field('category','Catégorie','select',state.settings.categories),field('description','Description','text',null,'','required'),amount,field('method','Moyen de paiement','select',['Espèces','Mvola','Holo','Virement','Carte','Chèque','Autre']),comment];
case 'maintenance':return [...common,field('vehicleId','Véhicule','select',state.vehicles.map(v=>[v.id,v.name]),currentVehicle().id),field('type','Type d’entretien','text',null,'Vidange','required'),field('km','Kilométrage','number',null,lastKm),field('cost','Coût payé','number',null,0),field('provider','Garage / prestataire'),field('nextDate','Prochaine date (facultatif)','date'),field('nextKm','Prochain kilométrage (0 = aucun)','number',null,0),comment];
case 'wages':return [...common,field('vehicleId','Véhicule d’affectation','select',state.vehicles.map(v=>[v.id,v.name]),currentVehicle().id),field('driverId','Chauffeur','select',state.drivers.map(d=>[d.id,d.name]),currentDriver().id),{...amount,label:'Salaire dû pour ce mois',value:d.salary},comment];
case 'driverPayments':return [...common,field('vehicleId','Véhicule d’affectation','select',state.vehicles.map(v=>[v.id,v.name]),currentVehicle().id),field('driverId','Chauffeur','select',state.drivers.map(d=>[d.id,d.name]),currentDriver().id),amount,comment];
case 'loans':return [field('lender','Organisme prêteur','text',null,'','required'),field('vehiclePrice','Prix du véhicule','number',null,v.purchasePrice),field('downPayment','Apport prévu','number',null,0),field('principal','Montant emprunté','number',null,0,'required'),field('rate','Taux nominal annuel (%)','number',null,0),field('count','Nombre d’échéances','number',null,24,'required'),field('frequency','Fréquence','select',[['monthly','Mensuelle'],['weekly','Hebdomadaire']],'monthly'),field('startDate','Date du contrat','date',null,C.today(),'required'),field('firstDue','Première échéance','date',null,C.addPeriod(C.today(),1),'required'),field('payment','Montant de l’échéance','number',null,0,'required'),field('fees','Frais contractuels prévus','number',null,0)];
case 'loanPayments':return [...common,field('loanId','Prêt','select',loansInScope().map(l=>[l.id,l.lender])),field('installment','N° de l’échéance','number',null,1,'required'),field('principal','Capital remboursé','number',null,0),field('interest','Intérêts payés','number',null,0),field('fees','Frais payés','number',null,0),comment];
case 'movements':return [...common,field('vehicleId','Véhicule (ou trésorerie commune)','select',[['','Commun au parc'],...state.vehicles.map(v=>[v.id,v.name])],scope),field('type','Type de mouvement','select',['Apport propriétaire','Retrait propriétaire','Autre entrée','Autre sortie','Achat véhicule','Déblocage du prêt']),field('ownerId','Propriétaire (pour apport / retrait)','select',state.owners.map(o=>[o.id,o.name])),amount,comment];
}}
function openForm(collection,id){if(collection==='loanPayments'&&!loansInScope().length){toast('Configurez d’abord votre prêt.');return;}if(collection==='wages'&&!id&&currentDriver().mode!=='fixed'){toast('Sélectionnez le salaire fixe dans Paramètres avant d’enregistrer un salaire mensuel.');return;}const old=id?state[collection].find(x=>x.id===id):null,fields=schema(collection),titles={days:'Journée de transport',expenses:'Dépense',maintenance:'Entretien',wages:'Salaire mensuel dû',driverPayments:'Paiement du chauffeur',loans:'Contrat de prêt',loanPayments:'Paiement du prêt',movements:'Mouvement de trésorerie'};const modal=$('#modal');modal.innerHTML=`<h2>${old?'Modifier · ':''}${titles[collection]}</h2><p class="sub">${esc(currentVehicle().name)} · ${esc(currentDriver().name)}</p>${collection==='days'?'<p class="sub">Le versement est reçu intégralement ; la commission sera payée séparément. En modification, la règle historique est conservée.</p>':''}${collection==='wages'?'<p class="sub">Une ligne par mois. Ce montant est dû, mais ne sort pas de la trésorerie avant son paiement.</p>':''}<form id="record-form"><div class="formgrid">${fields.map(f=>input(f,old?.[f.name])).join('')}${collection==='loans'?state.vehicles.map(v=>`<label>Financement attribué · ${esc(v.name)}<input type="number" min="0" step="0.01" name="allocation_${v.id}" value="${state.loanVehicles.find(a=>a.loanId===id&&a.vehicleId===v.id)?.amount||0}"></label>`).join(''):''}</div>${collection==='loans'?'<button type="button" id="calc-payment">Calculer l’échéance</button><p class="sub">Annuités constantes, intérêts sur capital restant. La dernière échéance ajuste le solde ; les frais sont exclus.</p>':''}${collection==='loanPayments'?'<button type="button" id="fill-installment">Préremplir selon l’échéancier</button><p class="sub">Vérifiez les montants sur le reçu du prêteur. Les paiements partiels peuvent être saisis.</p>':''}<div id="live-calc" class="notice" style="margin-top:16px"></div><div class="error" role="alert" id="form-error"></div><div class="formfoot"><button type="button" id="cancel">Annuler</button><button class="primary" type="submit">Enregistrer</button></div></form>`;modal.setAttribute('aria-label',modal.querySelector('h2')?.textContent||'Accès du membre');modal.showModal();$('#cancel').onclick=()=>modal.close();const form=$('#record-form');const calc=()=>{if(collection==='days'){const x=getValues(form,fields);$('#live-calc').textContent=`Distance : ${num(x.kmEnd-x.kmStart)} km · Écart : ${money(x.actual-x.expected)} · Commission : ${money(x.status==='Travaillé'?C.commission(x.actual,old?.terms||C.terms(state.drivers.find(d=>d.id===x.driverId))):0)}`;}else $('#live-calc').style.display='none';};form.addEventListener('input',calc);calc();if(collection==='days')form.elements.status.onchange=()=>{if(form.elements.status.value!=='Travaillé'){form.elements.expected.value=0;form.elements.actual.value=0;form.elements.kmEnd.value=form.elements.kmStart.value;form.elements.fuel.value=0;}calc();};
if(collection==='days'&&!old)form.elements.vehicleId.addEventListener('change',()=>{const vehicle=state.vehicles.find(v=>v.id===form.elements.vehicleId.value);const km=Math.max(vehicle.initialKm,...state.days.filter(d=>d.vehicleId===vehicle.id).map(d=>d.kmEnd));form.elements.kmStart.value=km;form.elements.kmEnd.value=km;calc();});
if($('#calc-payment'))$('#calc-payment').onclick=()=>{const x=getValues(form,fields);form.elements.payment.value=C.monthlyPayment(x.principal,x.rate,x.count,x.frequency);};
if($('#fill-installment'))$('#fill-installment').onclick=()=>{const x=getValues(form,fields),l=state.loans.find(l=>l.id===x.loanId),e=C.schedule(state,l).find(e=>e.number===x.installment);if(e){const ps=state.loanPayments.filter(p=>p.loanId===l.id&&p.installment===x.installment&&p.id!==id);form.elements.principal.value=Math.max(0,C.round(e.principal-C.sum(ps,p=>p.principal)));form.elements.interest.value=Math.max(0,C.round(e.interest-C.sum(ps,p=>p.interest)));}};
form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;try{let record={...old,...getValues(form,fields),id:id||C.uid()};if(['days','wages'].includes(collection))record.terms=old?.terms||C.terms(state.drivers.find(d=>d.id===record.driverId));await mutate(s=>{if(collection==='loans'){const allocations=state.vehicles.map(v=>({id:crypto.randomUUID(),loanId:record.id,vehicleId:v.id,amount:Number(form.elements['allocation_'+v.id]?.value||0)})).filter(a=>a.amount>0);s.loanVehicles=s.loanVehicles.filter(a=>a.loanId!==record.id).concat(allocations);}if(id)s[collection]=s[collection].map(x=>x.id===id?record:x);else s[collection].push(record);});modal.close();toast('Opération enregistrée.');}catch(e){$('#form-error').textContent=e.message;submit.disabled=false;}};}
async function remove(collection,id){if(collection==='loans'&&state.loanPayments.some(p=>p.loanId===id)){toast('Ce prêt a des paiements. Supprimez ses paiements avant de supprimer le contrat.');return;}confirmDialog('Supprimer cette opération ?','Son effet sur les totaux et la trésorerie sera également supprimé.',async()=>{await mutate(s=>{s[collection]=s[collection].filter(x=>x.id!==id);if(collection==='loans')s.loanVehicles=s.loanVehicles.filter(a=>a.loanId!==id);});toast('Opération supprimée.');});}
function confirmDialog(title,message,action,reinforced=false){const modal=$('#modal');modal.innerHTML=`<h2>${title}</h2><p>${esc(message)}</p><form id="confirm-form">${reinforced?'<label>Saisissez REINITIALISER pour confirmer<input name="confirm" autocomplete="off" required></label>':''}<div class="error" role="alert"></div><div class="formfoot"><button type="button" id="cancel">Annuler</button><button class="danger" type="submit">Confirmer</button></div></form>`;modal.setAttribute('aria-label',modal.querySelector('h2')?.textContent||'Accès du membre');modal.showModal();$('#cancel').onclick=()=>modal.close();$('#confirm-form').onsubmit=async e=>{e.preventDefault();if(reinforced&&e.target.elements.confirm.value!=='REINITIALISER'){modal.querySelector('.error').textContent='Saisissez exactement REINITIALISER.';return;}const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await action();modal.close();}catch(e){modal.querySelector('.error').textContent=e.message;button.disabled=false;}};}
function settingsFields(){return [
['Véhicule',[field('v_name','Nom / référence','text',null,'','required'),field('v_plate','Immatriculation'),field('v_brand','Marque'),field('v_model','Modèle'),field('v_year','Année','number'),field('v_purchasePrice','Prix d’achat','number'),field('v_purchaseDate','Date d’achat','date',null,'','required'),field('v_initialKm','Kilométrage initial','number'),field('v_status','Statut','select',['Actif','En panne','En entretien','Inactif']),field('v_notes','Notes véhicule','textarea')]],
['Exploitation',[field('s_target','Objectif journalier','number'),field('s_workdays','Jours mensuels indicatifs','number'),field('s_currency','Devise (3 lettres)','text',null,'','required pattern="[A-Z]{3}"'),field('s_fuelPayer','Carburant payé par défaut par','select',[['driver','Le chauffeur'],['owner','Les propriétaires']]),field('categories','Catégories de dépenses (une par ligne)','textarea')]],
['Chauffeur et rémunération',[field('d_name','Nom du chauffeur','text',null,'','required'),field('d_phone','Téléphone','tel'),field('d_startDate','Date de début','date',null,'','required'),field('d_status','Statut du chauffeur','select',['Actif','Absent','Inactif']),field('d_mode','Mode de rémunération','select',[['commission','Commission'],['fixed','Salaire fixe']]),field('d_salary','Salaire mensuel fixe','number'),field('d_commission','Commission par tranche','number'),field('d_tranche','Montant de la tranche','number'),field('d_rule','Règle des fractions de tranche','select',[['proportional','Proportionnelle (ex. 4 500 → 900)'],['full','Tranches complètes par jour (4 500 → 0)']]),field('d_notes','Observations chauffeur','textarea')]],
['Propriétaires',state.owners.map((o,i)=>field('owner_'+o.id,'Nom du propriétaire '+(i+1),'text',null,'','required'))]];}
function settingsPage(){const sections=settingsFields();return `<div class="notice">Les nouvelles règles s’appliquent aux prochaines saisies. Les journées et salaires existants conservent leur règle enregistrée. La devise change l’affichage uniquement : aucune conversion des montants. Sélectionnez le véhicule et le chauffeur à modifier dans les filtres.</div><form id="settings-form">${sections.map(([title,fields])=>`<section class="panel"><h2>${title}</h2><div class="formgrid">${fields.map(f=>{let value;if(f.name==='categories')value=state.settings.categories.join('\n');else if(f.name.startsWith('owner_'))value=state.owners.find(o=>o.id===f.name.slice(6)).name;else{const prefix=f.name.slice(0,2),key=f.name.slice(2);value=(prefix==='v_'?currentVehicle():prefix==='d_'?currentDriver():state.settings)[key];}return input(f,value);}).join('')}</div></section>`).join('')}<div class="error" id="settings-error" role="alert"></div><button class="primary" type="submit">Enregistrer les paramètres</button></form>`;}
function simFields(){const d=currentDriver();return [field('daily','Versement journalier estimé','number',null,state.settings.target),field('days','Jours travaillés','number',null,state.settings.workdays),field('target','Objectif journalier','number',null,state.settings.target),field('mode','Rémunération','select',[['commission','Commission'],['fixed','Salaire fixe']],d.mode),field('salary','Salaire fixe mensuel','number',null,d.salary),field('commission','Commission par tranche','number',null,d.commission),field('tranche','Montant de la tranche','number',null,d.tranche),field('rule','Calcul de la commission','select',[['proportional','Proportionnel'],['full','Tranches complètes par jour']],d.rule),field('loan','Remboursement mensuel prévu','number',null,C.sum(state.loans,l=>l.payment*(l.frequency==='weekly'?52/12:1))),field('expenses','Autres dépenses mensuelles','number',null,0),field('maintenance','Budget entretien','number',null,0),field('insurance','Assurance mensuelle','number',null,0),field('unexpected','Imprévus','number',null,0),field('other','Autres charges / carburant propriétaire','number',null,0)];}
function simulationPage(){return `<div class="notice">Ces hypothèses ne sont jamais enregistrées dans vos comptes. Le seuil affiché couvre les charges, la rémunération et le remboursement du prêt.</div><div class="grid2"><section class="panel"><h2>Vos hypothèses mensuelles</h2><form id="simulation-form"><div class="formgrid">${simFields().map(f=>input(f)).join('')}</div><div class="formfoot"><button class="primary" type="submit">Calculer les scénarios</button></div><div class="error" id="sim-error" role="alert"></div></form></section><section class="panel"><h2>Estimation</h2><div id="sim-result"></div></section></div><section class="panel"><h2>Comparer trois scénarios</h2><p class="sub">Prudent : versement journalier −20 %. Normal : vos hypothèses. Favorable : +20 %. Le nombre de jours et les coûts restent identiques.</p><div id="sim-scenarios"></div></section>`;}
function runSimulation(){const form=$('#simulation-form'),p=getValues(form,simFields());if(p.days<=0||p.days>31||p.tranche<=0||p.commission>=p.tranche){$('#sim-error').textContent='Prévoyez 1 à 31 jours, une tranche positive et une commission inférieure à la tranche.';return;}$('#sim-error').textContent='';const r=C.simulate(p);$('#sim-result').innerHTML=[['Versements estimés',money(r.revenue)],['Rémunération chauffeur',money(r.wage)],['Charges hors chauffeur',money(r.charges)],['Excédent avant prêt',money(r.profit)],['Remboursement prévu',money(p.loan)],['Net disponible estimé',sign(r.net)],['Marge après remboursement',num(r.margin)+' %'],['Seuil de versements / mois',r.breakEven===null?'Non atteignable':money(r.breakEven)],['Écart à l’objectif',sign(r.targetGap)]].map(([l,v])=>`<div class="metricrow"><span>${l}</span><b>${v}</b></div>`).join('');$('#sim-scenarios').innerHTML=table(['Scénario','Versement / jour','Versements mensuels','Chauffeur','Net après prêt','Marge'],[['Prudent',.8],['Normal',1],['Favorable',1.2]].map(([label,factor])=>{const daily=C.round(p.daily*factor),x=C.simulate({...p,daily});return[label,money(daily),money(x.revenue),money(x.wage),sign(x.net),num(x.margin)+' %'];}));}
function backupPage(){return `<div class="notice warn">Les saisies hors ligne sont conservées sur cet appareil puis synchronisées avec votre compte. Avant d’effacer les données du navigateur ou de changer d’appareil, vérifiez la synchronisation et téléchargez une sauvegarde JSON. La démonstration reste locale.</div><div class="grid2"><section class="panel"><h2>Télécharger une sauvegarde</h2><p>Un seul fichier JSON contient toutes vos opérations, vos paramètres et leurs règles historiques.</p><button class="primary" id="export">Télécharger une sauvegarde</button><p class="backup-date">Dernier téléchargement déclenché : ${state.settings.lastBackup?new Date(state.settings.lastBackup).toLocaleString('fr-FR'):'aucun'}</p><p class="sub">Vérifiez que le fichier est bien présent dans vos téléchargements. L’application ne peut pas vérifier sa conservation.</p></section><section class="panel"><h2>Restaurer une sauvegarde</h2><p>Le contenu sera vérifié avant confirmation. La restauration remplace les données métier de votre activité et sera synchronisée avec votre compte. Téléchargez d’abord la version actuelle. En démonstration, seul le contenu local est remplacé.</p><label>Fichier JSON<input type="file" id="import" accept=".json,application/json"></label><p class="sub">Un fichier invalide ou une version inconnue sera refusé sans modifier vos comptes.</p></section></div><section class="panel danger-zone"><h2>Zone dangereuse</h2><p>Téléchargez une sauvegarde avant de continuer. Ces actions remplacent les données actuelles.</p><div class="actions"><button class="danger" id="reset-demo">Réinitialiser avec les données de démonstration</button><button class="danger" id="reset-empty">Tout effacer</button></div></section><section class="panel"><h2>Fonctionnement hors ligne</h2><p id="cache-status">Vérification du cache local…</p><p class="sub">Ouvrez votre activité en ligne une première fois sur cet appareil. Vous pourrez ensuite retrouver vos données locales hors connexion. La synchronisation reprend au retour du réseau. L’installation est proposée par les navigateurs compatibles.</p><button id="persist-storage">Demander la conservation des données au navigateur</button></section>`;}
async function exportBackup(){const copy=structuredClone(state);copy.settings.lastBackup=new Date().toISOString();const blob=new Blob([JSON.stringify(C.backup(copy),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='nr-trans-backup-'+new Date().toISOString().slice(0,16).replace(/[T:]/g,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);if(DB.canWrite())await commit(copy);toast('Téléchargement lancé. Vérifiez votre dossier de téléchargements.');}
async function importBackup(file){if(!file)return;if(file.size>3*1024*1024)throw Error('Fichier trop volumineux (limite 3 Mo par sauvegarde).');const text=await file.text(),fingerprint=await Fleet.importFingerprint(text),restored=C.parseBackup(text),s=C.stats(restored);if(!DB.isDemo()&&restored.demo)throw Error('Les données fictives doivent rester dans l’espace de démonstration.');confirmDialog('Restaurer cette sauvegarde ?',`${restored.demo?'Démonstration':'Données réelles'} · ${restored.days.length} journées · ${restored.expenses.length} dépenses · ${restored.maintenance.length} entretiens · ${restored.loans.length} prêts · ${restored.loanPayments.length} remboursements · ${restored.driverPayments.length} paiements chauffeur. Solde : ${num(s.balance)} ${restored.settings.currency}. Les données métier actuelles seront remplacées et, pour votre compte réel, synchronisées avec le serveur.`,async()=>{state=await DB.save(restored,state.revision,{fingerprint});render();toast('Sauvegarde restaurée avec succès.');});}
function bind(){bindFleet();document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openForm(b.dataset.add));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openForm(b.dataset.edit,b.dataset.id));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>remove(b.dataset.delete,b.dataset.id));document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();});
if($('#apply-period'))$('#apply-period').onclick=()=>{if(!$('#from').value||!$('#to').value||$('#from').value>$('#to').value){toast('Choisissez une période valide.');return;}from=$('#from').value;to=$('#to').value;render();};
if($('#preset'))$('#preset').onchange=e=>{const t=C.today();switch(e.target.value){case'day':from=to=t;break;case'week':{let d=new Date(t+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));from=d.toISOString().slice(0,10);to=t;break;}case'month':from=t.slice(0,8)+'01';to=t;break;case'year':from=t.slice(0,4)+'-01-01';to=t;break;case'all':from='2000-01-01';to='2099-12-31';break;default:return;}render();};
if($('#status-filter'))$('#status-filter').onchange=e=>{statusFilter=e.target.value;render();};if($('#filter-search'))$('#filter-search').onclick=()=>{search=$('#search').value;render();};if($('#print'))$('#print').onclick=()=>window.print();
if($('#settings-form'))$('#settings-form').onsubmit=async e=>{e.preventDefault();const form=e.target;const button=form.querySelector('[type=submit]');button.disabled=true;try{const values=getValues(form,settingsFields().flatMap(x=>x[1]));await mutate(s=>{for(const [key,value]of Object.entries(values)){if(key==='categories'){s.settings.categories=[...new Set(value.split('\n').map(x=>x.trim()).filter(Boolean))];if(s.settings.categories.some(c=>['prêt','rémunération chauffeur','paiement chauffeur'].includes(c.toLowerCase())))throw Error('Prêt et rémunération chauffeur disposent de leurs propres modules.');}else if(key.startsWith('owner_'))s.owners.find(o=>o.id===key.slice(6)).name=value;else(key.startsWith('v_')?s.vehicles.find(v=>v.id===currentVehicle().id):key.startsWith('d_')?s.drivers.find(d=>d.id===currentDriver().id):s.settings)[key.slice(2)]=value;}});toast('Paramètres enregistrés.');}catch(e){$('#settings-error').textContent=e.message;button.disabled=false;}};
if($('#simulation-form')){$('#simulation-form').onsubmit=e=>{e.preventDefault();runSimulation();};runSimulation();}
if($('#export'))$('#export').onclick=()=>exportBackup().catch(error);if($('#import'))$('#import').onchange=e=>importBackup(e.target.files[0]).catch(error);
for(const type of (DB.isDemo()?['demo','empty']:[]))if($('#reset-'+type))$('#reset-'+type).onclick=()=>confirmDialog('Remplacer toutes les données ?', 'Cette opération supprimera les données actuelles de cet appareil. Téléchargez une sauvegarde avant de continuer.',async()=>{await commit(type==='demo'?C.demo():C.blank());toast(type==='demo'?'Démonstration chargée.':'Base vide créée.');},true);
if($('#persist-storage'))$('#persist-storage').onclick=async()=>{try{const ok=await navigator.storage?.persist?.();toast(ok?'Le navigateur a accordé le stockage persistant.':'Le navigateur n’a pas accordé le stockage persistant. Conservez vos sauvegardes.');}catch(e){error(e);}};
if($('#cache-status')){if('serviceWorker'in navigator)navigator.serviceWorker.getRegistration().then(r=>{if($('#cache-status'))$('#cache-status').textContent=r?.active?'Ressources mises en cache. L’application est prête pour une utilisation hors ligne.':'Le cache n’est pas encore actif. Rechargez après la première ouverture en ligne.';});else $('#cache-status').textContent='Cache PWA indisponible dans ce navigateur. Gardez une connexion active.';}
}
window.addEventListener('online',()=>{if($('#offline-status'))$('#offline-status').textContent='Stockage local';});window.addEventListener('offline',()=>{if($('#offline-status'))$('#offline-status').textContent='Hors connexion';});
try{await DB.openDB();state=await DB.read();if(state)C.validate(state);render();}catch(e){$('#workspace').innerHTML=`<div class="welcome"><h1>Ouverture impossible</h1><p>${esc(e.message)}</p><p>Ouvrez l’application avec son lanceur local et autorisez le stockage du navigateur. N’effacez pas vos données pour résoudre cette erreur.</p><button onclick="location.reload()">Réessayer</button></div>`;}
window.addEventListener('nr-data-refreshed',async()=>{
 const refresh=async()=>{state=await DB.current();render();};
 if($('#modal')?.open){toast('Une version serveur est disponible. Fermez le formulaire pour la consulter.');$('#modal').addEventListener('close',()=>refresh().catch(error),{once:true});}
 else await refresh().catch(error);
});

function fleetPage(){return '<div class="fleet-grid">'+state.vehicles.map(v=>{const s=Fleet.fleetStats(state,from,to,v.id);return '<section class="panel vehicle-card"><div class="vehicle-symbol">▱</div><span class="tag">'+esc(v.status)+'</span><h2>'+esc(v.name)+'</h2><p class="sub">'+esc(v.plate||'Immatriculation à renseigner')+'</p><div class="metricrow"><span>Versements</span><b>'+money(s.revenue)+'</b></div><div class="metricrow"><span>Résultat</span><b>'+money(s.profit)+'</b></div><button data-vehicle="'+esc(v.id)+'">Consulter ce véhicule</button></section>';}).join('')+'</div><section class="panel"><h2>Chauffeurs</h2>'+state.drivers.map(d=>'<div class="metricrow"><span>'+esc(d.name)+'</span><span>'+esc(d.status)+'</span></div>').join('')+'<button id="add-driver">Ajouter un chauffeur</button></section>';}
function bindFleet(){
 if($('#vehicle-scope'))$('#vehicle-scope').onchange=e=>{scope=e.target.value;render();};
 if($('#driver-scope'))$('#driver-scope').onchange=e=>{driverScope=e.target.value;render();};
 document.querySelectorAll('[data-vehicle]').forEach(b=>b.onclick=()=>{scope=b.dataset.vehicle;page='dashboard';render();});
 if($('#add-vehicle'))$('#add-vehicle').onclick=()=>simpleEntity('vehicles');
 if($('#add-driver'))$('#add-driver').onclick=()=>simpleEntity('drivers');
 if(!DB.canWrite())document.querySelectorAll('[data-add],[data-edit],[data-delete],#add-vehicle,#add-driver,#settings-form button,#reset-demo,#reset-empty,#import').forEach(e=>e.disabled=true);
 if(!DB.isDemo()){if($('#reset-demo'))$('#reset-demo').remove();if($('#reset-empty'))$('#reset-empty').remove();}
}
function simpleEntity(collection){
 if(collection==='vehicles'&&!DB.canAddVehicle(state.vehicles.length)){toast('Votre formule autorise un véhicule. Choisissez VIP dans votre espace Client pour agrandir le parc.');return;}
 const modal=$('#modal');modal.innerHTML='<h2>Ajouter '+(collection==='vehicles'?'un véhicule':'un chauffeur')+'</h2><form id="entity-form"><label>Nom<input name="name" required maxlength="120"></label><label>'+(collection==='vehicles'?'Immatriculation':'Téléphone')+'<input name="detail" maxlength="40"></label><div class="error" role="alert"></div><div class="formfoot"><button type="button" id="cancel">Annuler</button><button class="primary">Enregistrer</button></div></form>';modal.setAttribute('aria-label',modal.querySelector('h2')?.textContent||'Accès du membre');modal.showModal();$('#cancel').onclick=()=>modal.close();$('#entity-form').onsubmit=async e=>{e.preventDefault();try{const data=new FormData(e.target),blank=Base.blank()[collection][0],record={...blank,id:crypto.randomUUID(),name:data.get('name')};record[collection==='vehicles'?'plate':'phone']=data.get('detail');await mutate(s=>s[collection].push(record));modal.close();}catch(error){modal.querySelector('.error').textContent=error.message;}};
}
